data =
    from(bucket: "${bucket}")
        |> range(
            start: v.timeRangeStart,
            stop: v.timeRangeStop
        )

        |> filter(fn: (r) =>
            r["_measurement"] == "${meas}" and
            r["_field"] == "wire_voltage_status"
        )

        // Select Rack
        |> filter(fn: (r) =>
            r["storehouse_id"] == "${rack_id}"
        )

        // Only use pallet position L
        |> filter(fn: (r) =>
            r["pallet_position"] == "L"
        )

        // Only use Position 1
        |> filter(fn: (r) =>
            r["position_id"] == "1"
        )

        // Merge matching records into one table
        |> group()

        // Latest record first
        |> sort(
            columns: ["_time"],
            desc: true
        )

        // Keep only latest wire_voltage_status
        |> limit(n: 1)


wire_voltage_status =
    data
        |> set(
            key: "_field",
            value: "wire_voltage_status"
        )

        |> keep(columns: [
            "_value"
        ])


wire_voltage_status

from(bucket: "${bucket}")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )

    |> filter(fn: (r) =>
        r["_measurement"] == "${meas}" and
        r["_field"] =~ /^wire_voltage_[1-5]$/
    )

    |> filter(fn: (r) =>
        r["storehouse_id"] == "${rack_id}"
    )

    |> filter(fn: (r) =>
        r["pallet_position"] == "L"
    )

    |> filter(fn: (r) =>
        r["position_id"] == "1"
    )

    // Convert wire voltages into columns at the same timestamp
    |> pivot(
        rowKey: ["_time"],
        columnKey: ["_field"],
        valueColumn: "_value"
    )

    // Keep only complete voltage records
    |> filter(fn: (r) =>
        exists r.wire_voltage_1 and
        exists r.wire_voltage_2 and
        exists r.wire_voltage_3 and
        exists r.wire_voltage_4 and
        exists r.wire_voltage_5
    )

    // Merge into one table
    |> group()

    // Latest complete record first
    |> sort(
        columns: ["_time"],
        desc: true
    )

    // Keep only the latest complete record
    |> limit(n: 1)

    // Grafana Stat output
    |> map(fn: (r) => ({
        _field: "L",

        _value:
            string(v: r.wire_voltage_1) + " | " +
            string(v: r.wire_voltage_2) + " | " +
            string(v: r.wire_voltage_3) + " | " +
            string(v: r.wire_voltage_4) + " | " +
            string(v: r.wire_voltage_5) +
            (
                if r.wire_voltage_1 >= 1500 or
                   r.wire_voltage_2 >= 1500 or
                   r.wire_voltage_3 >= 1500 or
                   r.wire_voltage_4 >= 1500 or
                   r.wire_voltage_5 >= 1500
                then "."
                else ""
            )
    }))

